package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.period.ClosedPeriods;
import net.officefloor.hq.app.period.PeriodClosedException;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRetiredException;
import net.officefloor.hq.app.settings.Settings;
import net.officefloor.hq.app.sheet.InvalidSheetRequestException;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Builds the new claim, its due-by fixed from its person's own terms, else those of their grade in force on its date, a late entry when a soft-closed period contains its date, refusing one dated in a closed period or after its person's retirement date,
 *  and a correction that does not name a SETTLED claim of the same person. */
public class BuildClaim {
    public void build(@Val ClaimValues values, @Val Person person, Sheets sheets, ClosedPeriods closedPeriods,
            Claims claims, Settings settings, Out<Claim> claim) throws PeriodClosedException, PersonRetiredException, InvalidSheetRequestException {
        claim.set(built(values, person, sheets, closedPeriods, claims, settings));
    }

    /** The new DRAFT claim for these values and person, or refused by the claim form's rules. */
    static Claim built(ClaimValues values, Person person, Sheets sheets, ClosedPeriods closedPeriods,
            Claims claims, Settings settings) throws PeriodClosedException, PersonRetiredException, InvalidSheetRequestException {
        LocalDate date = values.date() != null ? values.date() : settings.claimDate(person.getSheetId());
        closedPeriods.refuse(person.getSheetId(), date);
        person.refuseRetired(date);
        refuseUncorrected(values, person.getSheetId(), person.getId(), claims);
        Claim built = new Claim(null, person.getSheetId(), person.getId(), values.amount(), date, values.note(),
                ClaimStatus.DRAFT, null, null, null);
        built.setCorrects(values.corrects());
        built.setDueBy(dueBy(person, date, settings));
        built.setLateEntry(closedPeriods.late(person.getSheetId(), date));
        return built;
    }

    /** The due-by of a claim of `person` dated `date`: its date plus the person's own terms, else
     *  the terms of their grade then, else the sheet's terms then. */
    static LocalDate dueBy(Person person, LocalDate date, Settings settings) {
        Integer own = person.getTerms();
        return date.plusDays(own != null ? own : settings.terms(person.getSheetId(), person.gradeOn(date), date));
    }

    /** Refuses a correction whose number is not a SETTLED claim of the same person. */
    static void refuseUncorrected(ClaimValues values, String sheetId, long personId, Claims claims)
            throws InvalidSheetRequestException {
        if (values.corrects() != null && !claims.settled(sheetId, personId, values.corrects())) {
            throw new InvalidSheetRequestException("A correction must name a settled claim of the same person: " + values.corrects());
        }
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.period.ClosedPeriods;
import net.officefloor.hq.app.period.PeriodClosedException;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRetiredException;
import net.officefloor.hq.app.sheet.InvalidSheetRequestException;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Val;

/** Edits the claim and releases its editor's lock, refusing when another user's editor locks it, or it is no longer a DRAFT, or is dated in a closed period, or would be moved into one,
 *  or would be dated after its person's retirement date, or would be a correction of no SETTLED claim of its person. */
public class ApplyClaim {
    public void apply(@Val ClaimValues values, @Val Claim claim, Sheets sheets, ClosedPeriods closedPeriods,
            People people, Claims claims)
            throws ClaimEditRefusedException, ClaimLockedException, PeriodClosedException, PersonRetiredException, InvalidSheetRequestException {
        ApplyClaimLock.refuseLocked(claim, values.user());
        if (claim.getStatus() != ClaimStatus.DRAFT) {
            throw new ClaimEditRefusedException(claim.getStatus());
        }
        LocalDate date = values.date() != null ? values.date() : sheets.today(claim.getSheetId());
        closedPeriods.refuse(claim.getSheetId(), claim.getDate());
        closedPeriods.refuse(claim.getSheetId(), date);
        Person person = people.find(claim.getSheetId(), claim.getPersonId());
        if (person != null) person.refuseRetired(date);
        BuildClaim.refuseUncorrected(values, claim.getSheetId(), claim.getPersonId(), claims);
        claim.setAmount(values.amount());
        claim.setDate(date);
        claim.setNote(values.note());
        claim.setCorrects(values.corrects());
        claim.setLockedBy(null);
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import java.util.Objects;
import net.officefloor.hq.app.period.ClosedPeriods;
import net.officefloor.hq.app.period.Period;
import net.officefloor.hq.app.period.PeriodClosedException;
import net.officefloor.hq.app.period.Periods;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.PersonRetiredException;
import net.officefloor.hq.app.settings.Role;
import net.officefloor.hq.app.settings.Settings;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Val;

/** A steward re-dates an OPEN or PENDING claim. Its due-by stays as it was fixed and a figure a
 *  statement bound stays bound; its period follows the new date, and while per-period numbering is
 *  on, a claim whose period changes takes the next number of its new period's sequence (its old
 *  number is never given again). Refused: anyone but a steward, a claim not OPEN or PENDING, a claim
 *  dated in a closed period or a new date in one, or a new date after its person's retirement. */
public class ApplyClaimRedate {
    public void apply(@Val ClaimRedate change, @Val Claim claim, People people, Settings settings, Sheets sheets,
            Periods periods, ClosedPeriods closedPeriods, ClaimNumbers numbers)
            throws ClaimStatusRefusedException, PeriodClosedException, PersonRetiredException {
        String sheetId = claim.getSheetId();
        if (sheets.archived(sheetId) || settings.role(sheetId, change.user()) != Role.STEWARD) {
            throw new ClaimStatusRefusedException("Only a steward can re-date a claim");
        }
        if (!claim.getStatus().isOpen()) {
            throw new ClaimStatusRefusedException("Only an OPEN or PENDING claim can be re-dated");
        }
        closedPeriods.refuse(sheetId, claim.getDate());
        closedPeriods.refuse(sheetId, change.date());
        people.find(sheetId, claim.getPersonId()).refuseRetired(change.date());
        LocalDate old = claim.getDate();
        change.redated(old);
        claim.setDate(change.date());
        LocalDate from = settings.periodNumberingFrom(sheetId);
        boolean perPeriod = from != null && !sheets.today(sheetId).isBefore(from);
        if (perPeriod && claim.getNumber() != null
                && !Objects.equals(sequence(periods, sheetId, old), sequence(periods, sheetId, change.date()))) {
            claim.setNumber(numbers.next(claim));
        }
    }

    private static String sequence(Periods periods, String sheetId, LocalDate date) {
        return periods.onSheet(sheetId).stream().filter(p -> p.contains(date))
                .map(Period::name).findFirst().orElse(ClaimNumbers.NO_PERIOD);
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import net.officefloor.hq.app.period.ClosedPeriods;
import net.officefloor.hq.app.period.PeriodClosedException;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.settings.Settings;
import net.officefloor.plugin.variable.Val;

/** Splits an amount off an OPEN claim (not deferred, nor dated in a closed period), for a user whose
 *  role may open a claim, and less than its amount: the claim keeps the rest, unbound from any
 *  statement; the new OPEN claim has the amount split off, the same date and note, the next number,
 *  is opened by the user, its due-by fixed from the terms in force on its date, and names the
 *  original's number as the one it was split from. */
public class ApplyClaimSplit {
    public void apply(@Val ClaimSplit split, @Val Claim claim, ClaimNumbers numbers, People people,
            ClosedPeriods closedPeriods, Settings settings) throws ClaimStatusRefusedException, PeriodClosedException {
        closedPeriods.refuse(claim.getSheetId(), claim.getDate());
        if (claim.getStatus() != ClaimStatus.OPEN || claim.isDeferred()) {
            throw new ClaimStatusRefusedException("Only an OPEN claim that is not deferred can be split");
        }
        if (!settings.allows(claim.getSheetId(), "open", split.user())) {
            throw new ClaimStatusRefusedException("Your role may not open a claim, so may not split one");
        }
        BigDecimal rest = claim.getAmount().subtract(split.amount());
        if (rest.signum() <= 0) {
            throw new ClaimStatusRefusedException("A split amount must be less than the claim's amount");
        }
        claim.setAmount(rest);
        claim.setStated(false);
        claim.setStatedDue(null);
        Person person = people.find(claim.getSheetId(), claim.getPersonId());
        Claim into = new Claim(null, claim.getSheetId(), claim.getPersonId(), split.amount(), claim.getDate(),
                claim.getNote(), ClaimStatus.OPEN, null, null, split.user());
        into.setDueBy(BuildClaim.dueBy(person, claim.getDate(), settings));
        into.setSplitFrom(claim.getNumber());
        into.setNumber(numbers.next(into));
        split.into(into);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.period.ClosedPeriods;
import net.officefloor.hq.app.period.PeriodClosedException;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonNotFoundException;
import net.officefloor.hq.app.person.PersonRetiredException;
import net.officefloor.hq.app.settings.Settings;
import net.officefloor.plugin.variable.Val;

/** Moves a DRAFT, OPEN or PENDING claim to another person on the sheet; only the roles the permission matrix allows may (a steward by
 *  default). The
 *  claim keeps its number and date but loses any figure a statement bound it to: it is live again
 *  until its new person's next statement. A SETTLED or VOID claim cannot move, nor a claim dated in
 *  a closed period, nor one dated after its new person's retirement date. */
public class ApplyClaimReassign {
    public void apply(@Val ClaimReassignment change, @Val Claim claim, People people, Settings settings,
            ClosedPeriods closedPeriods)
            throws ClaimStatusRefusedException, PersonNotFoundException, PersonRetiredException, PeriodClosedException {
        if (!settings.allows(claim.getSheetId(), "reassign", change.user())) {
            throw new ClaimStatusRefusedException("Your role may not reassign a claim");
        }
        if (claim.getStatus() != ClaimStatus.DRAFT && !claim.getStatus().isOpen()) {
            throw new ClaimStatusRefusedException("A " + claim.getStatus() + " claim cannot be reassigned");
        }
        Person to = people.find(claim.getSheetId(), change.toPersonId());
        if (to == null) throw new PersonNotFoundException(change.toPersonId());
        if (to.getId() == claim.getPersonId()) {
            throw new ClaimStatusRefusedException("The claim is already " + to.getName() + "'s: reassign it to another person");
        }
        closedPeriods.refuse(claim.getSheetId(), claim.getDate());
        to.refuseRetired(claim.getDate());
        Person from = people.find(claim.getSheetId(), claim.getPersonId());
        change.moved(from.getName(), to.getName());
        claim.setPersonId(to.getId());
        claim.setStated(false);
        claim.setStatedDue(null);
    }
}
package net.officefloor.hq.app.quickadd;

import net.officefloor.hq.app.claim.ClaimValues;
import net.officefloor.hq.app.period.ClosedPeriods;
import net.officefloor.hq.app.period.PeriodClosedException;
import net.officefloor.hq.app.settings.Settings;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Refuses a claim dated in a closed period before anything is saved, so no new person is left behind. */
public class RefuseClosedQuickAdd {
    public void refuse(@PathVariable("sheetId") String sheetId, @Val ClaimValues values, Settings settings,
            ClosedPeriods closedPeriods) throws PeriodClosedException {
        closedPeriods.refuse(sheetId, values.date() != null ? values.date() : settings.claimDate(sheetId));
    }
}
package net.officefloor.hq.app.period;

import java.time.LocalDate;
import org.springframework.stereotype.Service;

/** Guards claims dated in a closed period: none can be added, edited, opened, settled or voided. */
@Service
public class ClosedPeriods {

    private final Periods periods;

    public ClosedPeriods(Periods periods) {
        this.periods = periods;
    }

    /** Refuse a change to a claim dated `date` when a closed period contains it. */
    public void refuse(String sheetId, LocalDate date) throws PeriodClosedException {
        Period closed = periods.closedOn(sheetId, date);
        if (closed != null) throw new PeriodClosedException(closed, date);
    }

    /** Whether a claim dated `date` added now is a late entry: a soft-closed period contains it. */
    public boolean late(String sheetId, LocalDate date) {
        return periods.softClosedOn(sheetId, date) != null;
    }
}
package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.time.LocalDate;

/** A period of a sheet: its name, unique on the sheet, and its from and to dates, inclusive. A
 *  closed period keeps the due-total it had when it was closed (`closedTotal`). A soft-closed one
 *  (`closed` and `soft`) keeps it too, but claims dated in it can still be changed. */
public record Period(String sheetId, String name, LocalDate from, LocalDate to, boolean closed, BigDecimal closedTotal,
        boolean soft) {

    public Period(String sheetId, String name, LocalDate from, LocalDate to, boolean closed, BigDecimal closedTotal) {
        this(sheetId, name, from, to, closed, closedTotal, false);
    }

    /** A new, open period. */
    public Period(String sheetId, String name, LocalDate from, LocalDate to) {
        this(sheetId, name, from, to, false, null);
    }

    /** Whether the period is closed outright, not soft-closed: no claim dated in it can change. */
    public boolean hardClosed() {
        return closed && !soft;
    }

    /** Whether the two periods share a day. */
    public boolean overlaps(Period other) {
        return !from.isAfter(other.to) && !other.from.isAfter(to);
    }

    /** Whether the date falls in the period. */
    public boolean contains(LocalDate date) {
        return !date.isBefore(from) && !date.isAfter(to);
    }
}

